 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; fn extract_crate_info_simple (cargo_path : & Path) -> Result < Option < SimpleCrateInfo > > { let content = fs :: read_to_string (cargo_path) ? ; let toml : Value = toml :: from_str (& content) ? ; if let Some (package) = toml . get ("package") { if let Some (name) = package . get ("name") . and_then (| n | n . as_str ()) { return Ok (Some (SimpleCrateInfo { name : name . to_string () , })) ; } } Ok (None) }